package com.shopsphere.controller;
import com.shopsphere.dao.UserDAO; import com.shopsphere.model.User; import jakarta.servlet.*; import jakarta.servlet.annotation.WebServlet; import jakarta.servlet.http.*; import java.io.*;
@WebServlet("/profile") public class ProfileServlet extends HttpServlet{private final UserDAO users=new UserDAO();protected void doGet(HttpServletRequest q,HttpServletResponse p)throws ServletException,IOException{User u=(User)q.getSession().getAttribute("loggedInUser");q.setAttribute("profile",u);q.getRequestDispatcher("/WEB-INF/views/profile.jsp").forward(q,p);}protected void doPost(HttpServletRequest q,HttpServletResponse p)throws ServletException,IOException{User u=(User)q.getSession().getAttribute("loggedInUser");try{String n=q.getParameter("name")==null?"":q.getParameter("name").trim();String m=q.getParameter("mobile")==null?"":q.getParameter("mobile").trim();if(n.length()<2){q.setAttribute("error","Name must contain at least 2 characters.");doGet(q,p);return;}users.updateProfile(u.getUserId(),n,m);u.setName(n);u.setMobile(m);q.getSession().setAttribute("loggedInUser",u);q.setAttribute("success","Profile updated successfully.");doGet(q,p);}catch(Exception e){throw new ServletException("Unable to update profile",e);}}}